import{_ as i,k as a,A as s,a6 as l,E as n,j as o}from"./chunks/framework.Bul4SA1j.js";const k=JSON.parse('{"title":"v1.33.0","description":"The changelog for v1.33.0 (Update Name Placeholder).","frontmatter":{"title":"v1.33.0","page_title":"v1.33.0 (Update Name Placeholder) Changelog","description":"The changelog for v1.33.0 (Update Name Placeholder).","category":"Releases","mentions":["Andexter8"]},"headers":[{"level":2,"title":"Critical Bug Fixes","slug":"critical-bug-fixes","link":"#critical-bug-fixes","children":[]},{"level":2,"title":"Additions","slug":"additions","link":"#additions","children":[{"level":3,"title":"Player Menu","slug":"player-menu","link":"#player-menu","children":[]},{"level":3,"title":"Items","slug":"items","link":"#items","children":[]},{"level":3,"title":"UIs","slug":"uis","link":"#uis","children":[{"level":4,"title":"Settings","slug":"settings","link":"#settings","children":[]}]},{"level":3,"title":"Technical","slug":"technical","link":"#technical","children":[]}]},{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[{"level":3,"title":"Performance","slug":"performance","link":"#performance","children":[]},{"level":3,"title":"UIs","slug":"uis-1","link":"#uis-1","children":[]}]},{"level":2,"title":"Removals","slug":"removals","link":"#removals","children":[{"level":3,"title":"Script Form UI","slug":"script-form-ui","link":"#script-form-ui","children":[]}]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[{"level":3,"title":"Script Form UI","slug":"script-form-ui-1","link":"#script-form-ui-1","children":[]},{"level":3,"title":"UIs","slug":"uis-2","link":"#uis-2","children":[]}]}],"relativePath":"changelogs/v1.33.0.md","filePath":"changelogs/v1.33.0.md"}'),h={name:"changelogs/v1.33.0.md"};function r(u,e,d,c,m,g){const t=n("template-Stub");return o(),a("div",null,[s(t),e[0]||(e[0]=l('<h2 id="critical-bug-fixes" tabindex="-1">Critical Bug Fixes <a class="header-anchor" href="#critical-bug-fixes" aria-label="Permalink to &quot;Critical Bug Fixes&quot;">​</a></h2><h2 id="additions" tabindex="-1">Additions <a class="header-anchor" href="#additions" aria-label="Permalink to &quot;Additions&quot;">​</a></h2><h3 id="player-menu" tabindex="-1">Player Menu <a class="header-anchor" href="#player-menu" aria-label="Permalink to &quot;Player Menu&quot;">​</a></h3><p>Introducing the Player Menu.</p><p>It is like the Main Menu but it is for regular players instead of admins.</p><h3 id="items" tabindex="-1">Items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;Items&quot;">​</a></h3><ul><li>Added the Player Menu (<code class="shiki"><span>andexdb:player_menu</span></code>) item. This item opens the new Player Menu.</li></ul><h3 id="uis" tabindex="-1">UIs <a class="header-anchor" href="#uis" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><h4 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h4><ul><li>Added a new &quot;UI Settings&quot; section to the settings menu. <ul><li>The old &quot;UI Settings&quot; menu has been moved inside of this new menu at &quot;Main Menu &gt; Settings &gt; UI Settings &gt; Main&quot;.</li><li>Added the &quot;Menu Configurations&quot; settings menu to the new &quot;UI Settings&quot; settings menu. <ul><li>Added the &quot;Main Menu&quot; settings menus to the new &quot;Menu Configurations&quot; settings menu.</li><li>Added the &quot;Player Menu&quot; settings menus to the new &quot;Menu Configurations&quot; settings menu. <ul><li>Added the &quot;Main Settings&quot; settings menu to this menu. <ul><li>This menu contains the main settings for the player menu, such as whether or not it is enabled, whether buttons for upcoming features should be shown, and the item name for the item that players use to open the player menu.</li></ul></li><li>Added the &quot;Edit Buttons&quot; settings menu to this menu. <ul><li>This menu allows you to rearrange and/or remove the buttons in the player menu.</li></ul></li><li>Added the &quot;Leaderboards Settings&quot; settings menu to this menu. <ul><li>This menu allows you customize the leaderboards menu in the player menu.</li></ul></li><li>Added the &quot;Edit Warps&quot; settings menu to this menu. <ul><li>This menu allows you to add, edit, and remove warps for the warps section of the player menu.</li></ul></li><li>Added the &quot;Edit Redeemable Codes&quot; settings menu to this menu. <ul><li>This menu allows you to create/remove redeemable codes that players can redeem in the redeem code section of the player menu.</li></ul></li></ul></li></ul></li></ul></li><li>Added a new &quot;Teleport Systems Settings&quot; menu to the settings menu. <ul><li>This settings menu allows you to change settings that apply to all types of player-accessible teleports, including but not limited to the warps, TPA, and homes menus of the player menu, and the <a href="./../commands-list/-tpa.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpa</span></code></a>, <a href="./../commands-list/-spawn.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\spawn</span></code></a>, <a href="./../commands-list/-home.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\home</span></code></a>, and <a href="./../commands-list/-gohome.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\gohome</span></code></a> commands.</li></ul></li><li>Added a &quot;Player Menu Settings&quot; button to the settings menu, this button is an alias of &quot;Main Menu &gt; Settings &gt; UI Settings &gt; Menu Configurations &gt; Player Menu&quot;.</li></ul><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><ul><li>Added the following methods to <code class="shiki"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">Boolean</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">prototype</span></code>: <ul><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">toFormattedStringYN</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">(): </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;§aYes&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> | </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;§cNo&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">;</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">toFormattedStringYNB</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">(): </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;§2Yes&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> | </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;§4No&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">;</span></code></li></ul></li></ul><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>Made massive performances improvements to the Manage Players menu.</li><li>The list of bans is now cached to improve performance, and is automatically refreshed when you try to get the list of bans if the last refresh was at least a second before.</li></ul><h3 id="uis-1" tabindex="-1">UIs <a class="header-anchor" href="#uis-1" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Renamed the Global Settings menu to General Settings.</li></ul><h2 id="removals" tabindex="-1">Removals <a class="header-anchor" href="#removals" aria-label="Permalink to &quot;Removals&quot;">​</a></h2><h3 id="script-form-ui" tabindex="-1">Script Form UI <a class="header-anchor" href="#script-form-ui" aria-label="Permalink to &quot;Script Form UI&quot;">​</a></h3><ul><li>Removed the scrollable checkbox from the text fields, as the multiline mode without the scrollable capability is unnecessary. Now when you check the multiline checkbox, it acts like what enabling both multiline and scrollable would have done before.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="script-form-ui-1" tabindex="-1">Script Form UI <a class="header-anchor" href="#script-form-ui-1" aria-label="Permalink to &quot;Script Form UI&quot;">​</a></h3><ul><li>Fixed a bug where to select the multiline checkbox above the text fields when using controller, you had to use the right joystick to move the entire ui, instead of just being able to select it directly. A side effect of this is that if you click anywhere to the right of the multiline checkbox on touch or mouse, it will select it, which makes it much easier to press it.</li></ul><h3 id="uis-2" tabindex="-1">UIs <a class="header-anchor" href="#uis-2" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Fixed a bug where the search query would be cleared when switching pages in the manage players and view players with permission menus.</li></ul>',25))])}const f=i(h,[["render",r]]);export{k as __pageData,f as default};
